package main

import (
    "html"
)

func sanitizeUsername(username string) string {
    return html.EscapeString(username)
}

func getWelcomeMessage(username string) string {
    sanitizedUsername := sanitizeUsername(username)
    return "Welcome, " + sanitizedUsername + "!"
}

go
func getWelcomeMessage(username string) string {
    return "Welcome, " + username + "!"
}

// Test cases
print(getWelcomeMessage("testuser"))  // Should output: Welcome, testuser!
print(getWelcomeMessage(""))          // Should output: Welcome, !
print(getWelcomeMessage("Alice123"))   // Should output: Welcome, Alice123!
